raw:
{
  "spells": [
    {
      "id": "spell_water_07",
      "theory": "水绳术把魔力导入现场两升以上的水体，使水分子沿手势牵引的方向排列成束。水束能缠住一肢或同等粗细的轻物，载荷不超过两公斤。水绳依赖原有水体，离开水源后只能维持六十息。它不能固定沉重漂货，也无法把水变成绳索那样可以拖拽重物的工具。",
      "casting": "手掌浸入水中，以拇指与食指捏出一个环，将魔力沿环推入水内。另一只手向目标挥出弧线，水束便随弧线延伸缠绕。",
      "failure": "水束会在半途散落，打湿施术者袖口和地面。若环未闭合，水只鼓起一个泡便回落，声响像石块入水，可能惊动附近的人。",
      "counters": [
        "用刀或木片横切水束，媒介断开后束缚立即松脱。",
        "向水束撒入沙土，混浊的水体无法维持排列而散落。"
      ],
      "socialConsequences": "河谷乡约见证民事承诺时，常用它象征约束。渡口船工乐意用它临时拴住轻便货箱，但货主须自行承担松脱风险。渔人担心水绳惊走鱼群，常要求施术者远离下网处。城镇巡夜人若见有人用其缠住他人手腕，会追问事由，因为缠人肢体已超出普通约定的范围。",
      "law": {
        "river": "public",
        "city": "public",
        "port": "public"
      },
      "proficiencyEffects": [
        "初习者常把水束甩偏，只能缠住脚边静物，且耗水较多。",
        "稍熟者能稳定缠住一肢，水束粗细均匀，不易中途散落。",
        "熟练者可在目标移动时调整弧线，仍限于两公斤以内轻物。",
        "精熟者水束表面紧实，六十息内几乎不滴漏，载荷不变。"
      ]
    },
    {
      "id": "spell_water_08",
      "theory": "霜针术把魔力压入一小团水汽，使其在指尖前方凝成短冰针。冰针沿直线投射，击中后留下冻痕。炎热环境会加速冰针融化，威力随之下降。它不能拐弯，也不能同时射出多枚。冰针的射程与骨架一致，只作用于单一目标。",
      "casting": "掌心向上托起一团水汽，食指与中指并拢指向目标。魔力从指根涌向指尖，水汽在指尖前凝成针形，随即弹出。",
      "failure": "水汽会在掌心炸开，冻伤自己的指节，留下白斑和刺痛。若指向偏斜，冰针会扎入地面或墙面，碎成湿痕，暴露施术位置。",
      "counters": [
        "用厚布或皮盾挡在身前，冰针会扎入纤维并迅速融化。",
        "以火把靠近冰针路径，高温使针体在半途化为水滴。"
      ],
      "socialConsequences": "琥珀海岸的船主在港口用其驱赶偷食的鸟群，但须向港务申请许可。中陆城市公会允许持证者在指定靶场练习，未经许可在街巷投射会被追究责任，因为冰针可能误伤行人或损坏货物。冬季河面结冰时，乡约不禁止平民用其凿小孔取水，但若指向他人，则按伤人论处。",
      "law": {
        "river": "public",
        "city": "permit",
        "port": "permit"
      },
      "proficiencyEffects": [
        "初习者冰针粗细不匀，常在半途碎裂，只留下少量水渍。",
        "稍熟者能稳定凝出短针，命中静止目标，炎热中仍会减弱。",
        "熟练者冰针表面光滑，飞行更直，射程仍限于骨架范围。",
        "精熟者能在炎热中维持冰针成形稍久，威力上限不变。"
      ]
    },
    {
      "id": "spell_water_09",
      "theory": "河床听辨将魔力送入一小段水道，借回波感知浅滩与流速。它需要现场有水，并消耗一份树脂固定回波。感知只覆盖小段河道，不能预测整条河的走向，也无法探知深水下的沉物。持续九十息后回波消散，需重新施术。",
      "casting": "取树脂在掌心搓热，按入水面。另一手平贴水面，闭眼送出魔力，回波便沿水流返回掌心。",
      "failure": "掌心只感到杂乱震动，无法分辨浅滩。若树脂不足，回波会反冲施术者，引起短暂耳鸣和手指发麻，需休息片刻。",
      "counters": [
        "向水面投入石块，乱流会掩盖回波，使读数混乱。",
        "在上游开闸放水，流速骤变使回波无法稳定返回。"
      ],
      "socialConsequences": "渡口船夫依此判断浅滩，常请熟练者随行，但只测小段水道。渔人担心回波惊扰鱼群，要求施术者避开产卵区。港务在疏浚前会请人用其探路，但须确认树脂来源合法。若有人借听辨窥探他人泊位水深，货主可依港务规定追究责任，因为泊位水深属于航运信息。",
      "law": {
        "river": "public",
        "city": "public",
        "port": "public"
      },
      "proficiencyEffects": [
        "初习者回波杂乱，只能感到最近处深浅，范围很小。",
        "稍熟者能分辨小段浅滩，流速读数仍有明显误差。",
        "熟练者回波清晰，可标出浅滩边界，持续九十息。",
        "精熟者能在流水中稳定读数，范围仍限于小段水道。"
      ]
    }
  ]
}
